        Raylib.BeginDrawing();
        Raylib.ClearBackground(Raylib.RAYWHITE);

        Raylib.Rectangle(20, 20, 200, 40);
        if (Raygui.GuiButton("Reset") == 1) {
            width = 200.0f;
        }

        Raylib.Rectangle(20, 80, 300, 30);
        width = Raygui.GuiSlider("", "Width", width, 50.0f, 500.0f);

